interface.definition:
a!localVariables(
  local!users: if(
    a!isNotNullOrEmpty(ri!userid),
    #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1277768"(
      userId: ri!userid,
      isActive: true()
    ),
    {}
  ),
  if(
    a!isNotNullOrEmpty(local!users),
    #"SYSTEM_SYSRULES_forEach"(
      items: local!users,
      expression: #"SYSTEM_SYSRULES_cardLayout"(
        style: "NONE",
        showBorder: true,
        padding: "STANDARD",
        marginBelow: "STANDARD",
        contents: {
          /* Header */
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "user",
                color: "ACCENT",
                size: "MEDIUM"
              ),
              " ",
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "User Details",
                size: "LARGE",
                style: "STRONG",
                color: "ACCENT"
              )
            },
            marginBelow: "STANDARD"
          ),
          /* Vertical Grid — Field / Value rows */
          #"SYSTEM_SYSRULES_gridLayout"(
            headerCells: {
              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Field"),
              #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Value")
            },
            columnConfigs: {
              #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE", weight: 2),
              #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE", weight: 3)
            },
            rows: {
              /* Id */
              #"SYSTEM_SYSRULES_gridRowLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "hashtag", color: "STANDARD", size: "SMALL"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: "User Id", style: "STRONG")
                    }
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: if(
                        fv!item[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"] < 100000,
                        text(
                          fv!item[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"],
                          "#00000"
                        ),
                        fv!item[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"]
                      ),
                      color: "ACCENT",
                      style: "STRONG"
                    )
                  )
                }
              ),
              /* User Name */
              #"SYSTEM_SYSRULES_gridRowLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "user-circle-o", color: "STANDARD", size: "SMALL"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: "User Name", style: "STRONG")
                    }
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: a!defaultValue(
                        fv!item[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b6956f1b-0674-4b2a-a808-051a41257c01"],
                        "–"
                      ),
                      style: "STRONG"
                    )
                  )
                }
              ),
              /* First Name */
              #"SYSTEM_SYSRULES_gridRowLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "id-badge", color: "STANDARD", size: "SMALL"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: "First Name", style: "STRONG")
                    }
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: a!defaultValue(
                        fv!item[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/432735ea-6585-464d-b6e4-77009d9bcf1d"],
                        "–"
                      )
                    )
                  )
                }
              ),
              /* Email */
              #"SYSTEM_SYSRULES_gridRowLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: "envelope-o", color: "STANDARD", size: "SMALL"),
                      " ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Email", style: "STRONG")
                    }
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: a!defaultValue(
                        fv!item[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7e7ff32d-c4e1-468a-964f-48933b28c91e"],
                        "–"
                      ),
                      color: "ACCENT"
                    )
                  )
                }
              )
            },
            rowHeader: 1,
            borderStyle: "LIGHT",
            shadeAlternateRows: true
          )
        }
      )
    ),
    /* Empty state */
    #"SYSTEM_SYSRULES_cardLayout"(
      style: "STANDARD",
      padding: "STANDARD",
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          labelPosition: "COLLAPSED",
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "info-circle",
              color: "SECONDARY",
              size: "LARGE"
            ),
            char(10),
            char(10),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: "No Users Selected",
              size: "MEDIUM",
              style: "STRONG"
            ),
            char(10),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: "Select users to view their details.",
              size: "SMALL",
              color: "SECONDARY"
            )
          },
          align: "CENTER"
        )
      }
    )
  )
)
